        raw_desc = meta.get("description")
        desc = raw_desc.strip() if isinstance(raw_desc, str) else ""
        desc = desc or body.split("\n", 1)[0].lstrip("#").strip()
        SKILL_REGISTRY[name] = {
            "name": name,
            "description": desc,
            "content": raw,
        }


